const $=id=>document.getElementById(id);
let identity=null,state=null,socket=null,mode='create',wantsSocket=false,retry=null,selected=null,toastTimer=null,seenResult=0;
const STORAGE='al_masriya_private_auth_v02';
function readIdentity(){try{return JSON.parse(localStorage.getItem(STORAGE));}catch{return null;}}
function notify(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3800);}
function screen(page){$('home').hidden=page!=='home';$('room').hidden=page!=='room';$('resumeRoom').hidden=!readIdentity();}
function openDialog(type){mode=type;$('dialogTitle').textContent=type==='create'?'إنشاء غرفة خاصة':'دخول غرفة بالكود';$('dialogSubtitle').textContent=type==='create'?'اختار الاسم وعدد اللاعبين.':'ادخل الكود اللي دزّه صديقك.';$('sizeBox').hidden=type!=='create';$('codeBox').hidden=type!=='join';$('submitEntry').textContent=type==='create'?'إنشاء غرفة':'دخول الغرفة';$('playerName').value=localStorage.getItem('masriya_name')||'';$('entryDialog').showModal();$('playerName').focus();}
$('newRoom').onclick=()=>openDialog('create');$('joinRoom').onclick=()=>openDialog('join');$('closeDialog').onclick=()=>$('entryDialog').close();
$('entryCode').oninput=()=>{$('entryCode').value=$('entryCode').value.toUpperCase().replace(/[^A-HJ-NP-Z2-9]/g,'').slice(0,8);};
$('entryForm').onsubmit=async event=>{
 event.preventDefault();const name=$('playerName').value.trim();if(!name)return notify('اكتب اسمك أولاً.');
 const b=$('submitEntry');b.disabled=true;
 try{
  const url=mode==='create'?'/api/room/create':'/api/room/join';
  const payload=mode==='create'?{name,size:Number($('playerCount').value)}:{name,code:$('entryCode').value.trim()};
  const res=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await res.json();
  if(!res.ok)throw Error(data.error||'تعذر دخول الغرفة.');
  localStorage.setItem('masriya_name',name);identity={...data,name};localStorage.setItem(STORAGE,JSON.stringify(identity));
  $('entryDialog').close();showRoom();connect();
 }catch(e){notify(e.message);}finally{b.disabled=false;}
};
function showRoom(){screen('room');$('roomCode').textContent=identity.code;$('roomStatus').textContent='جارٍ الاتصال';}
function connect(){
 if(!identity)return;
 wantsSocket=true;clearTimeout(retry);
 if(socket){socket.onclose=null;try{socket.close();}catch{}}
 const proto=location.protocol==='https:'?'wss:':'ws:';
 socket=new WebSocket(`${proto}//${location.host}/api/room/${encodeURIComponent(identity.code)}/socket?playerId=${encodeURIComponent(identity.playerId)}&token=${encodeURIComponent(identity.token)}`);
 socket.onopen=()=>{$('roomStatus').textContent='🟢 متصل';};
 socket.onmessage=e=>{
  let data;try{data=JSON.parse(e.data);}catch{return;}
  if(data.type==='error')return notify(data.message);
  if(data.type==='state'){
   const old=state;state=data;
   if(old?.game?.deal!==data.game?.deal)selected=null;
   render();
  }
 };
 socket.onclose=e=>{
  $('roomStatus').textContent='🔴 اتصال منقطع';
  if(wantsSocket){clearTimeout(retry);retry=setTimeout(connect,3000);}
 };
 socket.onerror=()=>{$('roomStatus').textContent='🔴 تعذر الاتصال';};
}
function send(type,payload={}){if(socket?.readyState!==WebSocket.OPEN)return notify('اتصالك مو جاهز بعد.');socket.send(JSON.stringify({type,...payload}));}
function element(type,cls,text){const e=document.createElement(type);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e;}
function render(){
 if(!state)return;
 $('roomCode').textContent=state.code;
 const lobby=state.phase==='lobby';$('lobbyArea').hidden=!lobby;$('playArea').hidden=lobby;
 if(lobby)renderLobby();else renderGame();
}
function renderLobby(){
 const host=state.hostId===identity.playerId;
 $('roomMeta').textContent=`${state.size} لاعبين · ${state.size===4?'فريقين':'فردي'}`;
 $('startGame').hidden=!host;$('partnerBox').hidden=!host||state.size!==4;$('turnBox').hidden=!host;
 $('waitingMessage').textContent=`موجودين ${state.members.length} من ${state.size} — المقاعد الباقية يملأها الكمبيوتر تلقائياً.`;
 if(host&&state.size===4){const selectedPartner=state.partnerId||'';$('partner').replaceChildren(new Option('كمبيوتر / بدون اختيار',''));
  for(const p of state.members.filter(p=>p.id!==identity.playerId))$('partner').add(new Option(p.name,p.id));$('partner').value=selectedPartner;}
 $('turnSelect').value=String(state.settings?.turnSeconds||20);
 const slots=state.size===2?['bottom','top']:state.size===3?['bottom','left','right']:['bottom','left','top','right'];
 const seats=Array(state.size).fill(null);state.members.forEach((p,i)=>{if(i<state.size)seats[i]=p;});
 const grid=$('seatGrid');grid.replaceChildren();
 seats.forEach((p,i)=>{
  const div=element('div',`seat ${slots[i]} ${p?.id===identity.playerId?'mine':''} ${p?'':'empty'}`),badge=element('div','seat-badge');
  badge.append(element('div','seat-name',p?.name||'كمبيوتر عند البدء'),element('div','seat-meta',p?.id===state.hostId?'👑 المدير':'بانتظار بدء اللعب'));div.append(badge);grid.append(div);
 });
}
$('startGame').onclick=()=>send('start');$('partner').onchange=()=>send('choose_partner',{partnerId:$('partner').value||null});$('turnSelect').onchange=()=>send('set_turn',{seconds:Number($('turnSelect').value)});
$('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(identity.code);notify('اننسخ الكود، دزه لأصدقائك.');}catch{notify('كود الغرفة: '+identity.code);}};
$('resumeRoom').onclick=()=>{identity=readIdentity();if(identity){showRoom();connect();}};
$('backHome').onclick=()=>{
 wantsSocket=false;clearTimeout(retry);
 if(socket?.readyState===WebSocket.OPEN)send('leave');
 if(socket){socket.onclose=null;try{socket.close();}catch{}}socket=null;
 state=null;selected=null;screen('home');notify('تگدر ترجع للمباراة من زر الرجوع الموجود بالرئيسية.');
};

const AVATARS=["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];
const rank=c=>c?.rank==='JOKER'?'جوكر':c?.rank||'';
const suitColor=c=>['♥','♦'].includes(c?.suit)?'red-suit':'black-suit';
function cardNode(c,classes='',tag='button'){
 const div=element(tag,`playing-card ${suitColor(c)} ${classes} ${["J","Q","K"].includes(c.rank)?"face-card":""}`);
 if(c.rank==='JOKER'){div.textContent='🃏';div.classList.add('joker');}
 else {div.append(element('span','card-corner',`${c.rank}${c.suit}`),element('span','card-middle',c.suit),element('span','card-bottom',`${c.rank}${c.suit}`));}
 if(tag==='button')div.type='button';div.setAttribute('aria-label',`${rank(c)} ${c.suit||''}`);return div;
}
function cardBack(){return element('span','tiny-back','♠');}
function myTurn(g){return g.phase==='playing'&&!g.pending&&g.current===state.ownSeat;}
function canAct(g){return g.phase==='playing'&&state.ownSeat>=0;}
function renderGame(){
 const g=state.game;if(!g)return;
 const hosts=state.hostId===identity.playerId;
 $('roundNumber').textContent=`الجولة ${g.deal} · ${g.stockCount} بالسحب`;
 const now=g.pending?`طگة جارية — آخر لاعب: ${seatName(g.pending.lastSeat)}`:`الدور على ${seatName(g.current)}`;
 $('turnIndicator').textContent=g.phase==='playing'?now:g.phase==='between'?'نهاية الجولة':'انتهت المباراة';
 $('timerLabel').textContent=g.pending?'مهلة الطگ':'وقت الدور';
 $('stockNumber').textContent=g.stockCount;
 $('gameNotice').textContent=g.notice||'العب حسب دورك';
 $('nextDeal').hidden=!(g.phase==='between'&&hosts);
 $('restartGame').hidden=!(g.phase==='finished'&&hosts);
 renderScore(g);renderPlayers(g);renderGround(g);renderHand(g);renderResult(g);refreshTimer();
}
function seatName(i){return state?.seats?.[i]?.name||'الكمبيوتر';}
function renderScore(g){
 const board=$('scoreBoard');board.replaceChildren();
 g.scores.forEach((n,i)=>{const block=element('div','score-chip'),name=state.size===4?`فريق ${i+1}`:seatName(i);block.append(element('small','',name),element('strong','',`${n} / 1000`));board.append(block);});
}
function renderPlayers(g){
 const layer=$('playersLayer');layer.replaceChildren();
 const order=state.size===4?['bottom','left','top','right']:state.size===3?['bottom','left','right']:['bottom','top'];
 for(let seat=0;seat<state.size;seat++){
  const delta=(seat-(state.ownSeat>=0?state.ownSeat:0)+state.size)%state.size;
  const position=order[delta],player=state.seats[seat],pile=g.piles[seat];
  const box=element('div',`player-position pos-${position} ${seat===g.current?'acting':''} ${seat===state.ownSeat?'local-player':''}`);
  const badge=element('div','player-label');
  const avatar=element('span','player-face');const photo=element('img');photo.src=AVATARS[delta%AVATARS.length];photo.alt='';avatar.append(photo);badge.append(avatar);
  const details=element('div','player-details');details.append(element('strong','',player.name),element('small','',`${g.handCounts[seat]} بيده · ${player.bot||player.ai?'كمبيوتر':player.online?'متصل':'منقطع'}${state.size===4?` · فريق ${seat%2+1}`:''}`));
  badge.append(details);if(seat===g.current)badge.append(element('span','turn-dot','●'));box.append(badge);
  if(seat!==state.ownSeat){const cards=element('div','backs');for(let i=0;i<Math.min(5,g.handCounts[seat]);i++)cards.append(cardBack());box.append(cards);}
  const pileButton=element('button','pile-button');pileButton.type='button';pileButton.title='اضغط هنا للطگ على الكومة';
  if(pile?.top){
   pileButton.append(cardNode(pile.top,'pile-face','div'));
   const cap=element('div','pile-text',`فوگ ${pile.run} · مجموع ${pile.count}`);
   pileButton.append(cap);
   pileButton.setAttribute('aria-label',`كومة ${player.name}: آخر ورقة ${pile.top.rank}، عدد المتشابه ${pile.run}، مجموع الكومة ${pile.count}`);
  }
  else pileButton.textContent='كومة فارغة';
  pileButton.disabled=!pile.count||seat===state.ownSeat||!myTurn(g);
  pileButton.onclick=()=>attemptCapture('pile',seat);
  if(position==='bottom'&&seat===state.ownSeat){pileButton.classList.add('local-pile');layer.append(box);layer.append(pileButton);}else{box.append(pileButton);layer.append(box);}
 }
}
function canSlapSelected(g){
 if(!g || g.phase!=='playing' || !g.pending || state.ownSeat<0 || !selected)return false;
 if(g.pending.lastSeat===state.ownSeat)return false;
 if(g.stockCount===0 && g.hand.length<=1)return false;
 const c=g.hand.find(card=>card.id===selected);
 return !!c && (c.rank===g.pending.rank || c.rank==='JOKER');
}
function renderGround(g){
 const ground=$('groundCards');ground.replaceChildren();
 g.table.forEach(c=>{const node=cardNode(c,'ground-card');node.disabled=!myTurn(g);node.onclick=()=>attemptCapture('table',c.id);ground.append(node);});
 // Keep ground cards visible while a slap contest is taking place.
 // The contested cards are shown separately, but the remaining table cards never disappear.
 $('slapZone').hidden=!g.pending;
 $('groundCards').hidden=false;
 $('groundCards').setAttribute('aria-label',`الكاع: ${g.table.length} ورقة مكشوفة`);
 const caption= document.querySelector('.ground-caption');
 if(caption)caption.textContent=`الكاع · ${g.table.length} ورقة مكشوفة`;

 if(g.pending){$('slapInfo').textContent=`⚡ منافسة على ${g.pending.rank} · آخر طگة: ${seatName(g.pending.lastSeat)} · ${g.pending.cards.length} ورقات`;
  $('slapCards').replaceChildren(...g.pending.cards.slice(-9).map(c=>cardNode(c,'slap-reveal','div')));
  $('slapButton').disabled=!canSlapSelected(g);
  $('slapButton').onclick=()=>{if(!canSlapSelected(g))return notify('اختار ورقة مطابقة للطگة أو جوكر.');send('move',{move:{type:'slap',cardId:selected}});};
 }
}
function renderHand(g){
 const area=$('myCards');area.replaceChildren();
 const playable=canAct(g);const validIds=new Set(g.hand.map(c=>c.id));if(selected&&!validIds.has(selected))selected=null;
 g.hand.forEach(c=>{const node=cardNode(c,`hand-card ${selected===c.id?'chosen':''}`);node.onclick=()=>{if(!playable)return;selected=selected===c.id?null:c.id;renderHand(g);if(g.pending){$('slapButton').disabled=!canSlapSelected(g);}};area.append(node);});
 $('discardButton').disabled=!myTurn(g)||!selected||(g.stockCount===0&&g.hand.length<=1);
 $('moveInstruction').textContent=g.phase==='between'?'الجولة انتهت — بانتظار المدير':g.phase==='finished'?'المباراة انتهت':g.pending?'حتى لو طگيت قبل، تكدر ترجع تطگ إذا أحد ردّ عليك — اختار ورقة مطابقة واضغط طگ':myTurn(g)?'دورك: اختار ورقة ثم اضغط على ورقة بالكاع أو كومة خصم، أو اضغط «لكح»':'تگدر تجهز ورقة للطگ إذا تدخلت على حركة لاعب';
}
function attemptCapture(source,target){
 const g=state?.game;if(!g||!myTurn(g))return;
 if(!selected)return notify('حدد ورقة من إيدك أولاً.');
 send('move',{move:source==='table'?{type:'capture',cardId:selected,source,targetId:target}:{type:'capture',cardId:selected,source,targetSeat:target}});
}
$('discardButton').onclick=()=>{if(selected)send('move',{move:{type:'discard',cardId:selected}});};
$('nextDeal').onclick=()=>send('next_deal');$('restartGame').onclick=()=>send('restart');
function renderResult(g){
 const box=$('resultBox');box.hidden=g.phase==='playing';box.replaceChildren();if(g.phase==='playing')return;
 const heading=element('strong','result-title',g.phase==='finished'?'🏆 انتهت المباراة!':g.lastResult?.replay?'🤝 تعادل — تنعاد الجولة':'✅ نتيجة الجولة');box.append(heading);
 const res=g.lastResult;if(res){
  const table=element('div','result-grid');res.groups.forEach((v,i)=>{
   const a=element('div','result-row');a.append(element('span','',state.size===4?`فريق ${i+1}`:seatName(i)),element('b','',`${v} نقطة`),element('span','',res.awards[i]?`+${res.awards[i]} مسجلة`:'0 مسجلة'));table.append(a);
  });box.append(table);
  box.append(element('small','',g.phase==='finished'?'وصل أحد اللاعبين أو الفرق إلى 1000 نقطة.':'صاحب الغرفة يبدأ الجولة التالية.'));
 }
}
function refreshTimer(){
 const g=state?.game;let seconds=0;
 if(g?.clock){seconds=Math.max(0,Math.ceil((g.clock.deadline-Date.now())/1000));}
 $('countdown').textContent=String(seconds).padStart(2,'0');
 $('countdown').classList.toggle('danger',seconds<=4&&g?.phase==='playing');
}
setInterval(refreshTimer,200);
window.addEventListener('online',()=>{if(wantsSocket&&socket?.readyState!==WebSocket.OPEN)connect();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
identity=readIdentity();screen('home');
